    correlation_id character varying(255),
    causation_id character varying(255),
    source_id uuid,
    depth integer DEFAULT 0 NOT NULL,
    data jsonb NOT NULL,
    workspace_id character varying(255) NOT NULL,
    created_by character varying(255) NOT NULL,
    source_type character varying(64),
    session_key character varying(512),
    sender character varying(512),
    attachments jsonb DEFAULT '[]'::jsonb NOT NULL,
    routed_at timestamp with time zone,
    subscribers integer,
    reacted integer DEFAULT 0 NOT NULL,
    skipped integer DEFAULT 0 NOT NULL,
    errors integer DEFAULT 0 NOT NULL
)
PARTITION BY RANGE (received_at);


