--
-- Name: stream_sources; Type: TABLE; Schema: public
--

CREATE TABLE public.stream_sources (
    id uuid NOT NULL,
    workspace_id character varying(255) NOT NULL,
    created_by character varying(255) NOT NULL,
    created_at timestamp without time zone DEFAULT now() NOT NULL,
    updated_at timestamp without time zone DEFAULT now() NOT NULL,
    stream_id uuid NOT NULL,
    kind character varying(32) NOT NULL,
    webhook_id character varying(255),
    webhook_type character varying(50),
    webhook_config json,
    credential_key uuid,
    event_templates json,
    poll_cursor text,
    polled_at timestamp with time zone,
    poll_error text,
    registered_url text,
    subscription_id text,
    refresh_before timestamp with time zone,
    senders json,
    CONSTRAINT ck_stream_sources_platform CHECK ((((kind)::text <> 'platform'::text) OR (webhook_id IS NULL))),
    CONSTRAINT ck_stream_sources_poll CHECK ((((kind)::text <> 'poll'::text) OR ((webhook_id IS NULL) AND (webhook_type IS NOT NULL) AND (credential_key IS NOT NULL)))),
    CONSTRAINT ck_stream_sources_webhook CHECK ((((kind)::text <> 'webhook'::text) OR ((webhook_id IS NOT NULL) AND (webhook_type IS NOT NULL) AND (credential_key IS NOT NULL))))
);


