    created_at timestamp without time zone DEFAULT now() NOT NULL,
    updated_at timestamp without time zone DEFAULT now() NOT NULL,
    stream_id uuid NOT NULL,
    kind character varying(32) NOT NULL,
    trigger_id uuid,
    filter json DEFAULT '{}'::json NOT NULL,
    output_stream_ids json DEFAULT '[]'::json NOT NULL,
    status character varying(16) DEFAULT 'active'::character varying NOT NULL,
    started_at timestamp with time zone DEFAULT now() NOT NULL,
    external_id character varying(64),
    subscriber character varying(255),
    callback_url text,
    secret_name character varying(255),
    expires_at timestamp with time zone,
    verified_at timestamp with time zone,
    last_delivery_at timestamp with time zone,
    last_error character varying(32),
    failed_since timestamp with time zone,
    code text,
    CONSTRAINT ck_stream_subscriptions_external CHECK ((((kind)::text <> 'external'::text) OR ((external_id IS NOT NULL) AND (subscriber IS NOT NULL) AND (callback_url IS NOT NULL) AND (secret_name IS NOT NULL) AND (expires_at IS NOT NULL)))),
    CONSTRAINT ck_stream_subscriptions_processor CHECK ((((kind)::text <> 'processor'::text) OR (code IS NOT NULL))),
    CONSTRAINT ck_stream_subscriptions_trigger CHECK ((((kind)::text <> 'trigger'::text) OR (trigger_id IS NOT NULL)))
);


